schema_ddl:
CREATE TABLE agenti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    provvigione NUMERIC(4,2) CHECK (provvigione >= 0 AND provvigione <= 100)
);

CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ragione_sociale TEXT NOT NULL,
    partita_iva TEXT NOT NULL UNIQUE
);

CREATE TABLE ordini (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    agente_id INT REFERENCES agenti(id),
    data_ordine DATE NOT NULL DEFAULT CURRENT_DATE,
    importo_totale NUMERIC(12,2) NOT NULL CHECK (importo_totale >= 0)
);
